def getHappyString(n, k):
    if n == 1:
        return "abc"[k-1] if k <= 3 else ""
    total = 3 * (1 << (n-2))
    if k > 3 * total:
        return ""
    third = total // 3
    if k <= third:
        return "a" + getHappyString(n-1, k)
    elif k <= 2 * third:
        return "b" + getHappyString(n-1, k - third)
    else:
        return "c" + getHappyString(n-1, k - 2 * third)
